import { test, expect, Page } from '@playwright/test'
import AxeBuilder from '@axe-core/playwright'

const BASE_URL = process.env.PLAYWRIGHT_BASE_URL ?? 'http://localhost:3000'

// ── Fixtures ──────────────────────────────────────────────────

const TEST_USER = {
  email: `e2e-candidate-${Date.now()}@platform-test.com`,
  password: 'E2eTestPass1!',
  fullName: 'E2E Test Candidate',
}

// ── Helpers ───────────────────────────────────────────────────

async function registerAndLogin(page: Page) {
  await page.goto(`${BASE_URL}/register`)
  await page.getByLabel('Full name').fill(TEST_USER.fullName)
  await page.getByLabel('Email').fill(TEST_USER.email)
  await page.getByLabel('Password').fill(TEST_USER.password)
  await page.getByRole('radio', { name: 'Candidate' }).check()
  await page.getByRole('button', { name: 'Create account' }).click()
  // In test env, email verification is auto-confirmed for @platform-test.com emails
  await expect(page.getByText('Check your email')).toBeVisible()
  await page.goto(`${BASE_URL}/login`)
  await page.getByLabel('Email').fill(TEST_USER.email)
  await page.getByLabel('Password').fill(TEST_USER.password)
  await page.getByRole('button', { name: 'Sign in' }).click()
  await expect(page).toHaveURL(/\/dashboard/)
}

// ── US-01: Candidate Registration ────────────────────────────

test.describe('US-01 — Candidate Registration', () => {
  test('registers with email and password, sees verification notice', async ({ page }) => {
    await page.goto(`${BASE_URL}/register`)

    await page.getByLabel('Full name').fill('New Candidate')
    await page.getByLabel('Email').fill(`new-${Date.now()}@platform-test.com`)
    await page.getByLabel('Password').fill('NewPass123!')
    await page.getByRole('radio', { name: 'Candidate' }).check()
    await page.getByRole('button', { name: 'Create account' }).click()

    await expect(page.getByText(/check your email/i)).toBeVisible()
  })

  test('shows error for duplicate email', async ({ page }) => {
    await page.goto(`${BASE_URL}/register`)
    await page.getByLabel('Full name').fill('Duplicate')
    await page.getByLabel('Email').fill('existing@platform-test.com') // pre-seeded in test env
    await page.getByLabel('Password').fill('Pass123!')
    await page.getByRole('radio', { name: 'Candidate' }).check()
    await page.getByRole('button', { name: 'Create account' }).click()

    await expect(page.getByText(/already registered/i)).toBeVisible()
  })

  test('registration page has no critical accessibility violations', async ({ page }) => {
    await page.goto(`${BASE_URL}/register`)
    const results = await new AxeBuilder({ page }).analyze()
    const critical = results.violations.filter(v => v.impact === 'critical' || v.impact === 'serious')
    expect(critical, `Accessibility violations: ${JSON.stringify(critical, null, 2)}`).toHaveLength(0)
  })
})

// ── US-02: Candidate Profile Setup ───────────────────────────

test.describe('US-02 — Profile Setup', () => {
  test.beforeEach(async ({ page }) => { await registerAndLogin(page) })

  test('uploads a resume and sees parsed skills confirmed', async ({ page }) => {
    await page.goto(`${BASE_URL}/profile`)
    await page.getByLabel('Interview track').selectOption('software_engineering')
    await page.getByLabel('Career level').selectOption('mid')

    const fileInput = page.getByLabel('Upload resume')
    await fileInput.setInputFiles({
      name: 'test-resume.pdf',
      mimeType: 'application/pdf',
      buffer: Buffer.from('%PDF-1.4 test resume content'),
    })

    await expect(page.getByText(/we extracted/i)).toBeVisible({ timeout: 15_000 })
    await page.getByRole('button', { name: 'Confirm & Continue' }).click()
    await expect(page).toHaveURL(/\/dashboard/)
  })

  test('rejects files larger than 5MB', async ({ page }) => {
    await page.goto(`${BASE_URL}/profile`)
    const largeBuffer = Buffer.alloc(6 * 1024 * 1024, 'x')
    const fileInput = page.getByLabel('Upload resume')
    await fileInput.setInputFiles({ name: 'large.pdf', mimeType: 'application/pdf', buffer: largeBuffer })
    await expect(page.getByText(/file size exceeds/i)).toBeVisible()
  })
})

