// ── US-05: Browse & Filter Question Bank ─────────────────────

test.describe('US-05 — Question Bank Browse & Filter', () => {
  test.beforeEach(async ({ page }) => { await registerAndLogin(page) })

  test('displays paginated questions and applies type filter', async ({ page }) => {
    await page.goto(`${BASE_URL}/question-bank`)
    await expect(page.getByTestId('question-list')).toBeVisible()

    const initialCount = await page.locator('[data-testid="question-card"]').count()
    expect(initialCount).toBeGreaterThan(0)

    await page.getByLabel('Type').selectOption('behavioral')
    await expect(page.getByLabel('Type')).toHaveValue('behavioral')
    // Filter chip appears
    await expect(page.getByText('behavioral')).toBeVisible()

    const filteredCount = await page.locator('[data-testid="question-card"]').count()
    expect(filteredCount).toBeGreaterThan(0)
  })

  test('shows sample answer collapsed behind toggle', async ({ page }) => {
    await page.goto(`${BASE_URL}/question-bank`)
    await page.locator('[data-testid="question-card"]').first().click()
    await expect(page.getByRole('button', { name: /show answer/i })).toBeVisible()
    await page.getByRole('button', { name: /show answer/i }).click()
    await expect(page.getByTestId('sample-answer')).toBeVisible()
  })
})

// ── US-06: Search ─────────────────────────────────────────────

test.describe('US-06 — Search & Discovery', () => {
  test.beforeEach(async ({ page }) => { await registerAndLogin(page) })

  test('shows autocomplete suggestions after 2 characters', async ({ page }) => {
    await page.goto(`${BASE_URL}/question-bank`)
    const searchInput = page.getByRole('searchbox', { name: /search/i })
    await searchInput.fill('le')
    await expect(page.getByTestId('autocomplete-suggestions')).toBeVisible({ timeout: 2_000 })
    const suggestions = page.locator('[data-testid="autocomplete-suggestion"]')
    await expect(suggestions).toHaveCount({ minimum: 1 })
  })

  test('shows no-results state for unmatched query', async ({ page }) => {
    await page.goto(`${BASE_URL}/question-bank`)
    await page.getByRole('searchbox', { name: /search/i }).fill('xyznonexistentquery123')
    await expect(page.getByText(/no results/i)).toBeVisible({ timeout: 2_000 })
  })
})

// ── US-09: AI Mock Interview ──────────────────────────────────

test.describe('US-09 — AI Mock Interview Session', () => {
  test.use({
    // Grant camera/mic permissions for recording tests
    permissions: ['camera', 'microphone'],
  })

  test.beforeEach(async ({ page }) => { await registerAndLogin(page) })

  test('shows consent dialog before session starts', async ({ page }) => {
    await page.goto(`${BASE_URL}/mock-interview`)
    await page.getByRole('button', { name: /start ai mock/i }).click()
    await expect(page.getByRole('dialog', { name: /consent/i })).toBeVisible()
  })

  test('start session button is disabled until consent checkbox is checked', async ({ page }) => {
    await page.goto(`${BASE_URL}/mock-interview`)
    await page.getByRole('button', { name: /start ai mock/i }).click()

    const acceptButton = page.getByRole('button', { name: /accept.*start/i })
    await expect(acceptButton).toBeDisabled()

    await page.getByRole('checkbox', { name: /i have read/i }).check()
    await expect(acceptButton).toBeEnabled()
  })

  test('declining consent closes dialog and does not start session', async ({ page }) => {
    await page.goto(`${BASE_URL}/mock-interview`)
    await page.getByRole('button', { name: /start ai mock/i }).click()
    await page.getByRole('button', { name: /decline/i }).click()
    await expect(page.getByRole('dialog')).not.toBeVisible()
    await expect(page).toHaveURL(/\/mock-interview/)
  })

  test('consent dialog has no critical accessibility violations', async ({ page }) => {
    await page.goto(`${BASE_URL}/mock-interview`)
    await page.getByRole('button', { name: /start ai mock/i }).click()
    await expect(page.getByRole('dialog')).toBeVisible()
    const results = await new AxeBuilder({ page }).analyze()
    const critical = results.violations.filter(v => v.impact === 'critical' || v.impact === 'serious')
    expect(critical).toHaveLength(0)
  })
})

// ── US-15: Feedback Archive ───────────────────────────────────

test.describe('US-15 — Feedback Archive', () => {
  test.beforeEach(async ({ page }) => { await registerAndLogin(page) })

  test('lists sessions in reverse chronological order', async ({ page }) => {
    await page.goto(`${BASE_URL}/feedback`)
    const entries = page.locator('[data-testid="feedback-entry"]')
    const count = await entries.count()
    // Fresh account — no sessions yet
    if (count === 0) {
      await expect(page.getByText(/no sessions yet/i)).toBeVisible()
    } else {
      // Verify descending order by checking data-date attributes
      const dates = await entries.evaluateAll(
        (els) => els.map((el) => el.getAttribute('data-date') ?? ''),
      )
      const sorted = [...dates].sort((a, b) => b.localeCompare(a))
      expect(dates).toEqual(sorted)
    }
  })

  test('feedback archive page has no critical accessibility violations', async ({ page }) => {
    await page.goto(`${BASE_URL}/feedback`)
    const results = await new AxeBuilder({ page }).analyze()
    const critical = results.violations.filter(v => v.impact === 'critical' || v.impact === 'serious')
    expect(critical).toHaveLength(0)
  })
})
